import io.heapy.kotdoc.crypto.*;import kotlin.*;import java.math.BigInteger;class RsaMaxReview{static int calls;static class G implements CryptoDrg<G>{public Pair<byte[],G>randomBytesGenerate(int n){throw new AssertionError();}}public static void main(String[]args){var rsa=new CryptoRsa(new CryptoNumberPrime(new CryptoProbabilistic(n->new byte[n])));CryptoDrgOperations<G>ops=(n,g)->{calls++;byte[]b=new byte[n];java.util.Arrays.fill(b,(byte)255);return new Pair<>(LazyKt.lazyOf(b),LazyKt.lazyOf(new G()));};try{CryptoRandom.INSTANCE.withDRG(new G(),rsa.generateBlinderAction(LazyKt.lazyOf(BigInteger.valueOf(129)),ops)).getFirst().getValue();}catch(Throwable e){System.out.println(e.getClass().getSimpleName()+":"+e.getMessage()+" calls="+calls);}}}
